"""Friday 29 January: explorers' day."""

SQUADS = ['Y1', 'O1', 'G1', 'Y2', 'O2', 'G2']


def carousel(n_stations, times):
    """Rows of a rotation table: squad i starts at station i+1 and moves on one each round."""
    rows = []
    for i, sq in enumerate(SQUADS):
        rows.append([sq] + [str((i + r) % n_stations + 1) for r in range(len(times))])
    return rows


